// Verdict regression table: named, realistic AI-written documents with the
// expected per-sentence status and isClean. Each row names the hunt finding
// (2026-10-10) it pins, or "guard" for behavior that must not regress.
// test/verdict-table.test.ts runs every row.

import type { ClassifyConfig, SentenceStatus } from "../../src/index.js";

export interface VerdictRow {
  name: string;
  finding: string;
  text: string;
  evidence: Record<string, string>;
  config?: ClassifyConfig;
  expect: SentenceStatus[];
  clean: boolean;
}

const G = "grounded" as const;
const U = "ungrounded" as const;
const I = "invalid" as const;
const P = "placeholder" as const;

export const EV = {
  bat: "independent lab testing measured 14 hours of battery life on a full charge at default brightness",
  bat2: "the battery lasts 14 hours on a full charge",
  war: "the warranty is one year and covers manufacturing defects",
  wgt: "the laptop weighs 1.2 kilograms with the battery installed",
  acme: "the unit is manufactured and distributed by Acme Inc across North America and Europe",
  us: "the unit is sold in every state across the U.S. through authorized retailers",
  lunch: "lunch is served at noon in the main cafeteria",
  junk: "the cafeteria serves soup on fridays",
};

